options.css:
@ pre {
	width: 750px;
	white-space: pre-wrap;
	word-break: break-all;
	word-wrap: break-word; /* for IE11 */
	line-break: anywhere;
	margin: 5px 0px
}@ 

.badge {
    display: inline-block;
    padding: .25em .4em;
    margin: 0 .1em;
    font-weight: 700;
    line-height: 1;
    text-align: center;
    white-space: nowrap;
    vertical-align: baseline;
    border-radius: .25rem;

    color: #000;
    background-color: #E0E2E5;
}@ 

.badge-small {
    font-size: 75%;
}@ 

.badge-error {
	color: #fff;
	background-color: #a94442
}@

